HEAD = ["cr_id", "group", "priority", "requirement_short", "source", "code_location", "static_verdict",
        "notes", "related_leads", "existing_tests", "how_field_test_will_check", "dataset_categories"]


def main() -> None:
    rows = []
    for r in ROWS:
        cr = r[0]
        rows.append([cr, cr[3], *r[1:]])
    with (OUT / "traceability_matrix.csv").open("w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(HEAD)
        w.writerows(rows)

    by_group: dict[str, Counter] = defaultdict(Counter)
    must: Counter = Counter()
    total: Counter = Counter()
    for r in rows:
        by_group[r[1]][r[6]] += 1
        total[r[6]] += 1
        if r[2] == "M":
            must[r[6]] += 1
    verdicts = [I, P, N, NA]
    lines = ["# Traceability summary (STATIC verdicts, Step 1)", "",
             "These verdicts come from reading the code. Nothing here is a test result yet; the field test confirms or changes them.", "",
             "| Group | " + " | ".join(verdicts) + " | Total |", "|---|" + "---|" * (len(verdicts) + 1)]
    for g in sorted(by_group):
        c = by_group[g]
        lines.append(f"| {g} | " + " | ".join(str(c[v]) for v in verdicts) + f" | {sum(c.values())} |")
    lines.append("| **All** | " + " | ".join(str(total[v]) for v in verdicts) + f" | {sum(total.values())} |")
    lines.append("| **MUST only** | " + " | ".join(str(must[v]) for v in verdicts) + f" | {sum(must.values())} |")
    (OUT / "traceability_summary.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("\n".join(lines))


if __name__ == "__main__":
    main()
